svg.script:
(function(){
  const root=document.documentElement;
  function apply(el, painted){ el.dataset.painted=painted?'1':'0'; el.style.fill=painted?el.dataset.color:el.dataset.base; }
  function trigger(el, all){
    const next=el.dataset.painted!=='1';
    if(all){ root.querySelectorAll('.paint-region[data-number="'+el.dataset.number+'"]') .forEach(x=>apply(x,next)); }
    else apply(el,next);
  }
  root.querySelectorAll('.paint-region').forEach(el=>{
    if(!el.dataset.base){ el.dataset.base=getComputedStyle(el).fill; }
    el.addEventListener('click',e=>trigger(el,e.shiftKey));
    el.addEventListener('keydown',e=>{ if(e.key==='Enter'||e.key===' '){e.preventDefault();trigger(el,e.shiftKey);} });
  });
  root.querySelectorAll('.swatch').forEach(sw=>sw.addEventListener('click',()=>{
    root.querySelectorAll('.paint-region[data-number="'+sw.dataset.paletteNumber+'"]') .forEach(x=>apply(x,true));
  }));
})();
